#include "permute_params.h"
#include "ascendc/core/ascendc.h"

class PermuteKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR paramsGm)
    {
        AscendC::TPipe pipe;
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(x));
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t *>(y));

        AscendC::GlobalTensor<PermuteParams> paramsGmTensor;
        paramsGmTensor.SetGlobalBuffer(reinterpret_cast<__gm__ PermuteParams *>(paramsGm), 1);
        AscendC::DataCopyParams copyParams{1, sizeof(PermuteParams), 0, 0, 0};
        AscendC::DataCopy(paramsGm_, paramsGmTensor, copyParams);
        AscendC::PipeBarrier<AscendC::PIPE_ALL>();

        ndim_ = paramsGm_.ndim;
        for (int32_t i = 0; i < ndim_; i++) {
            dims_[i] = paramsGm_.dims[i];
            inShape_[i] = paramsGm_.inShape[i];
            outShape_[i] = paramsGm_.outShape[i];
            inStride_[i] = paramsGm_.inStride[i];
        }
        totalElements_ = paramsGm_.totalElements;
        lastDimSize_ = paramsGm_.lastDimSize;
        totalRows_ = paramsGm_.totalRows;
        startRow_ = paramsGm_.startRow;
        endRow_ = paramsGm_.endRow;

        elementSize_ = sizeof(T);
        srcStrideBytes_ = inStride_[dims_[ndim_ - 1]] * elementSize_;
    }

    __aicore__ inline void Process()
    {
        int32_t coreId = AscendC::GetCoreId();
        int32_t coreNum = AscendC::GetCoreNum();

        int64_t rowsPerCore = (totalRows_ + coreNum - 1) / coreNum;
        int64_t startRow = coreId * rowsPerCore;
        int64_t endRow = (startRow + rowsPerCore > totalRows_) ? totalRows_ : (startRow + rowsPerCore);
        if (startRow >= totalRows_) {
            return;
        }

        uint64_t xBase = reinterpret_cast<uint64_t>(xGm_.GetPhyAddr());
        uint64_t yBase = reinterpret_cast<uint64_t>(yGm_.GetPhyAddr());

        for (int64_t row = startRow; row < endRow; row++) {
            int64_t temp = row;
            int64_t coord[MAX_NDIM] = {0};
            for (int32_t dim = ndim_ - 2; dim >= 0; dim--) {
                coord[dim] = temp % outShape_[dim];
                temp /= outShape_[dim];
            }

            int64_t sourceOffsetElements = 0;
            for (int32_t p = 0; p < ndim_ - 1; p++) {
                sourceOffsetElements += coord[p] * inStride_[dims_[p]];
            }

            uint64_t srcAddr = xBase + static_cast<uint64_t>(sourceOffsetElements) * static_cast<uint64_t>(elementSize_);
            uint64_t dstAddr = yBase + static_cast<uint64_t>(row) * static_cast<uint64_t>(lastDimSize_) * static_cast<uint64_t>(elementSize_);

            uint32_t blockCount = static_cast<uint32_t>(lastDimSize_);
            uint32_t blockSize = static_cast<uint32_t>(elementSize_);
            uint32_t srcStride = static_cast<uint32_t>(srcStrideBytes_);

            AscendC::DataCopyExtParams copyParams{blockCount, blockSize, srcStride, 0, 0};
            AscendC::DataCopyPad(reinterpret_cast<__gm__ T *>(dstAddr),
                                 reinterpret_cast<__gm__ T *>(srcAddr),
                                 copyParams);
        }
    }

private:
    __gm__ uint8_t *xGm_;
    __gm__ uint8_t *yGm_;
    PermuteParams paramsGm_;
    int32_t ndim_;
    int64_t dims_[MAX_NDIM];
    int64_t inShape_[MAX_NDIM];
    int64_t outShape_[MAX_NDIM];
    int64_t inStride_[MAX_NDIM];
    int64_t totalElements_;
    int64_t lastDimSize_;
    int64_t totalRows_;
    int64_t startRow_;
    int64_t endRow_;
    int32_t elementSize_;
    uint32_t srcStrideBytes_;
};
