#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_permute_fp16.h"
#include "aclrtlaunch_permute_fp32.h"
#include "aclrtlaunch_permute_bf16.h"
#include "../permute_params.h"
#include <cstring>

namespace ascend_kernel {

static int64_t ComputeStride(const int64_t *shape, int64_t dim, int64_t ndim)
{
    int64_t stride = 1;
    for (int64_t d = dim + 1; d < ndim; d++) {
        stride *= shape[d];
    }
    return stride;
}

at::Tensor permute(const at::Tensor &x, const at::Tensor &dimsTensor)
{
    TORCH_CHECK(x.device().is_privateuseone(), "x must be on NPU");
    TORCH_CHECK(dimsTensor.device().is_privateuseone(), "dims must be on NPU");
    TORCH_CHECK(x.dim() >= 2 && x.dim() <= 4, "x must be 2D/3D/4D");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int64_t ndim = x.dim();
    TORCH_CHECK(dimsTensor.numel() == ndim, "dims length must match x dims");

    // Copy dims to CPU
    at::Tensor dimsCpu = dimsTensor.to(at::kCPU).contiguous();
    const int64_t *dimsData = dimsCpu.data_ptr<int64_t>();

    // Compute output shape
    std::vector<int64_t> outShapeVec;
    for (int64_t i = 0; i < ndim; i++) {
        int64_t d = dimsData[i];
        TORCH_CHECK(d >= 0 && d < ndim, "invalid dim in dims");
        outShapeVec.push_back(x.size(d));
    }

    // Compute input strides (in elements)
    int64_t inStrideArr[4] = {0};
    for (int64_t i = 0; i < ndim; i++) {
        inStrideArr[i] = ComputeStride(x.sizes().data(), i, ndim);
    }

    // Create output tensor
    at::Tensor y = at::empty(outShapeVec, x.options());

    // Compute output strides (unused in kernel, but needed for completeness)
    int64_t outStrideArr[4] = {0};
    for (int64_t i = 0; i < ndim; i++) {
        outStrideArr[i] = ComputeStride(outShapeVec.data(), i, ndim);
    }

    // Total elements and tiling
    int64_t totalElements = y.numel();
    int64_t lastDimSize = outShapeVec[ndim - 1];
    int64_t totalRows = totalElements / lastDimSize;

    // Get core count
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = ascendcPlatform->GetCoreNum();
    if (coreNum <= 0) coreNum = 1;
    int64_t usedCoreNum = (totalRows < coreNum) ? totalRows : coreNum;
    if (usedCoreNum <= 0) usedCoreNum = 1;

    // Prepare params on CPU
    at::Tensor paramsCpu = at::empty(
        {static_cast<int64_t>(sizeof(PermuteParams))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *params = reinterpret_cast<PermuteParams *>(paramsCpu.data_ptr());

    for (int64_t i = 0; i < ndim; i++) {
        params->dims[i] = dimsData[i];
        params->inShape[i] = x.size(i);
        params->outShape[i] = outShapeVec[i];
        params->inStride[i] = inStrideArr[i];
    }
    // Zero out unused entries for safety
    for (int64_t i = ndim; i < 4; i++) {
        params->dims[i] = 0;
        params->inShape[i] = 0;
        params->outShape[i] = 0;
        params->inStride[i] = 0;
    }
    params->ndim = ndim;
    params->totalElements = totalElements;
    params->lastDimSize = lastDimSize;
    params->totalRows = totalRows;

    // Compute per-core row ranges
    int64_t rowsPerCore = (totalRows + usedCoreNum - 1) / usedCoreNum;

    // Launch kernel for each core
    at::Tensor paramsNpu = paramsCpu.to(at::kPrivateUse1);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    auto scalarType = x.scalar_type();
    bool isFp16 = (scalarType == at::kHalf);
    bool isBf16 = (scalarType == at::kBFloat16);

    if (isFp16) {
        for (int64_t c = 0; c < usedCoreNum; c++) {
            int64_t startRow = c * rowsPerCore;
            int64_t endRow = (startRow + rowsPerCore > totalRows) ? totalRows : (startRow + rowsPerCore);
            if (startRow >= totalRows) break;

            PermuteParams coreParams;
            std::memcpy(&coreParams, params, sizeof(PermuteParams));
            coreParams.startRow = startRow;
            coreParams.endRow = endRow;

            at::Tensor coreParamsCpu = at::empty(
                {static_cast<int64_t>(sizeof(PermuteParams))},
                at::device(at::kCPU).dtype(at::kByte));
            std::memcpy(coreParamsCpu.data_ptr<uint8_t>(), &coreParams, sizeof(PermuteParams));
            at::Tensor coreParamsNpu = coreParamsCpu.to(at::kPrivateUse1);

            EXEC_KERNEL_CMD(permute_fp16, blockDim, x, y, coreParamsNpu);
        }
    } else if (isBf16) {
        for (int64_t c = 0; c < usedCoreNum; c++) {
            int64_t startRow = c * rowsPerCore;
            int64_t endRow = (startRow + rowsPerCore > totalRows) ? totalRows : (startRow + rowsPerCore);
            if (startRow >= totalRows) break;

            PermuteParams coreParams;
            std::memcpy(&coreParams, params, sizeof(PermuteParams));
            coreParams.startRow = startRow;
            coreParams.endRow = endRow;

            at::Tensor coreParamsCpu = at::empty(
                {static_cast<int64_t>(sizeof(PermuteParams))},
                at::device(at::kCPU).dtype(at::kByte));
            std::memcpy(coreParamsCpu.data_ptr<uint8_t>(), &coreParams, sizeof(PermuteParams));
            at::Tensor coreParamsNpu = coreParamsCpu.to(at::kPrivateUse1);

            EXEC_KERNEL_CMD(permute_bf16, blockDim, x, y, coreParamsNpu);
        }
    } else {
        for (int64_t c = 0; c < usedCoreNum; c++) {
            int64_t startRow = c * rowsPerCore;
            int64_t endRow = (startRow + rowsPerCore > totalRows) ? totalRows : (startRow + rowsPerCore);
            if (startRow >= totalRows) break;

            PermuteParams coreParams;
            std::memcpy(&coreParams, params, sizeof(PermuteParams));
            coreParams.startRow = startRow;
            coreParams.endRow = endRow;

            at::Tensor coreParamsCpu = at::empty(
                {static_cast<int64_t>(sizeof(PermuteParams))},
                at::device(at::kCPU).dtype(at::kByte));
            std::memcpy(coreParamsCpu.data_ptr<uint8_t>(), &coreParams, sizeof(PermuteParams));
            at::Tensor coreParamsNpu = coreParamsCpu.to(at::kPrivateUse1);

            EXEC_KERNEL_CMD(permute_fp32, blockDim, x, y, coreParamsNpu);
        }
    }

    return y;
}

} // namespace ascend_kernel
