import torch
from pathlib import Path


def _load_kernel():
    """Find and load the kernel shared library from possible locations."""
    search_dirs = [
        Path(__file__).parent,  # package directory (installed case)
        Path(__file__).parent.parent / "kernel" / "build",  # dev case
    ]
    # Also try current working directory
    try:
        search_dirs.append(Path.cwd() / "kernel" / "build")
    except Exception:
        pass

    loaded = False
    for search in search_dirs:
        try:
            for so_file in search.glob("_kernel.*.so"):
                try:
                    torch.ops.load_library(str(so_file))
                    loaded = True
                except Exception:
                    pass
        except Exception:
            pass
    return loaded


_loaded = _load_kernel()
if not _loaded:
    # Last resort: try any _kernel.so on the system (unlikely but safe fallback)
    import glob as g
    for path in g.glob("**/_kernel.*.so"):
        try:
            torch.ops.load_library(path)
            break
        except Exception:
            pass
