 */

#pragma once

#include "permute_params.h"
#include "kernel_common.h"

template<typename T>
class PermuteKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR paramsGm)
    {
        CopyTiling(&params_, paramsGm);
        ndim_ = params_.ndim;
        lastDimSize_ = params_.lastDimSize;
        totalRows_ = params_.totalRows;
        startRow_ = params_.startRow;
        endRow_ = params_.endRow;
        for (int32_t i = 0; i < ndim_; i++) {
            dims_[i] = params_.dims[i];
            inStride_[i] = params_.inStride[i];
            outShape_[i] = params_.outShape[i];
        }
        // srcStride in bytes for the last output dimension
        srcStrideBytes_ = static_cast<uint32_t>(
            inStride_[dims_[ndim_ - 1]] * static_cast<int64_t>(sizeof(T)));
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x));
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y));
    }

    __aicore__ inline void Process()
    {
        if (startRow_ >= endRow_) return;

        uint64_t xBase = reinterpret_cast<uint64_t>(xGM_.GetPhyAddr());
        uint64_t yBase = reinterpret_cast<uint64_t>(yGM_.GetPhyAddr());

        // Check if strided read fits in DataCopyParams
        bool canStridedRead = (srcStrideBytes_ <= 65535U) && (lastDimSize_ <= 4095U);

        for (int64_t row = startRow_; row < endRow_; row++) {
            // Decompose row index into output coordinates (excluding last dim)
            int64_t temp = row;
            int64_t coord[4] = {0};
            for (int32_t d = ndim_ - 2; d >= 0; d--) {
                coord[d] = temp % outShape_[d];
                temp /= outShape_[d];
            }

            // Compute source element offset
            int64_t sourceOffset = 0;
            for (int32_t p = 0; p < ndim_ - 1; p++) {
                sourceOffset += coord[p] * inStride_[dims_[p]];
            }

            uint64_t srcBase = xBase + static_cast<uint64_t>(sourceOffset) * static_cast<uint64_t>(sizeof(T));
            uint64_t dstBase = yBase + static_cast<uint64_t>(row) * static_cast<uint64_t>(lastDimSize_) * static_cast<uint64_t>(sizeof(T));

            if (canStridedRead) {
                // Use strided DataCopy: read strided source, contiguous output
                uint16_t count = static_cast<uint16_t>(lastDimSize_);
                uint16_t blkLen = static_cast<uint16_t>(sizeof(T));
                uint16_t srcStride = static_cast<uint16_t>(srcStrideBytes_);
                AscendC::DataCopyParams copyParams{count, blkLen, srcStride, 0};
                AscendC::DataCopy(yGM_[dstBase], xGM_[srcBase], copyParams);
            } else {
                // Element-by-element copy using contiguous reads/writes
                AscendC::DataCopyParams elemCopy{1, static_cast<uint16_t>(sizeof(T)), 0, 0};
                for (int64_t e = 0; e < lastDimSize_; e++) {
                    int64_t srcOff = sourceOffset + e * inStride_[dims_[ndim_ - 1]];
                    AscendC::DataCopyParams elemIn{1, static_cast<uint16_t>(sizeof(T)), 0, 0};
                    // Read one element from strided source into temp buffer
                    AscendC::DataCopy(ubLocal_, xGM_[xBase + static_cast<uint64_t>(srcOff) * static_cast<uint64_t>(sizeof(T)), elemIn);
                    // Write one element to output
                    AscendC::DataCopy(yGM_[dstBase + e * static_cast<uint64_t>(sizeof(T))], ubLocal_, elemCopy);
                }
            }
        }
    }

private:
    ascend_kernel::PermuteParams params_{};
    int32_t ndim_{0};
    int64_t dims_[4];
    int64_t inStride_[4];
    int64_t outShape_[4];
    int64_t lastDimSize_{0};
    int64_t totalRows_{0};
    int64_t startRow_{0};
    int64_t endRow_{0};
    uint32_t srcStrideBytes_{0};

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;
    AscendC::LocalTensor<T> ubLocal_;  // single element temp buffer
};
