#pragma once

#include "permute_params.h"
#include "kernel_common.h"

template<typename T>
class PermuteKernel {
public:
    static constexpr int32_t BATCH_SIZE = 16;

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR paramsGm, AscendC::TPipe* pipe)
    {
        CopyTiling(&params_, paramsGm);
        ndim_ = params_.ndim;
        lastDimSize_ = params_.lastDimSize;
        totalRows_ = params_.totalRows;
        startRow_ = params_.startRow;
        endRow_ = params_.endRow;
        for (int32_t i = 0; i < ndim_; i++) {
            dims_[i] = params_.dims[i];
            inStride_[i] = params_.inStride[i];
            outShape_[i] = params_.outShape[i];
        }
        srcStrideElements_ = inStride_[dims_[ndim_ - 1]];
        slotStride_ = 32 / static_cast<int32_t>(sizeof(T));
        int32_t bufBytes = BATCH_SIZE * slotStride_ * static_cast<int32_t>(sizeof(T));
        pipe_->InitBuffer(batchQueue_, 1, static_cast<uint32_t>(bufBytes));
        batchLocal_ = batchQueue_.AllocTensor<T>();
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x));
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y));
    }

    __aicore__ inline void Process()
    {
        if (startRow_ >= endRow_) return;
        for (int64_t row = startRow_; row < endRow_; row++) {
            int64_t temp = row;
            int64_t coord[4] = {0};
            for (int32_t d = ndim_ - 2; d >= 0; d--) {
                coord[d] = temp % outShape_[d];
                temp /= outShape_[d];
            }
            int64_t sourceOffset = 0;
            for (int32_t p = 0; p < ndim_ - 1; p++) {
                sourceOffset += coord[p] * inStride_[dims_[p]];
            }
            int64_t dstBase = row * lastDimSize_;
            ProcessRow(sourceOffset, dstBase);
        }
    }

private:
    __aicore__ inline void ProcessRow(int64_t sourceOffset, int64_t dstBase)
    {
        // Phase 1: read elements into 32-byte aligned slots in UB
        for (int64_t e = 0; e < lastDimSize_; e += BATCH_SIZE) {
            int64_t batchSize = lastDimSize_ - e;
            if (batchSize > BATCH_SIZE) batchSize = BATCH_SIZE;
            for (int64_t s = 0; s < batchSize; s++) {
                int64_t srcOff = sourceOffset + (e + s) * srcStrideElements_;
                int32_t slot = static_cast<int32_t>(s) * slotStride_;
                AscendC::DataCopy(batchLocal_[slot], xGM_[srcOff], 1);
            }
            AscendC::PipeBarrier<PIPE_ALL>();
            // Phase 2: write elements from slots to output
            for (int64_t s = 0; s < batchSize; s++) {
                int64_t dstOff = dstBase + e + s;
                int32_t slot = static_cast<int32_t>(s) * slotStride_;
                AscendC::DataCopy(yGM_[dstOff], batchLocal_[slot], 1);
            }
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

    ascend_kernel::PermuteParams params_{};
    int32_t ndim_{0};
    int64_t dims_[4];
    int64_t inStride_[4];
    int64_t outShape_[4];
    int64_t lastDimSize_{0};
    int64_t totalRows_{0};
    int64_t startRow_{0};
    int64_t endRow_{0};
    int64_t srcStrideElements_{0};
    int32_t slotStride_{0};

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> batchQueue_;
    AscendC::LocalTensor<T> batchLocal_;
};
