Permute AscendC wrapper.
Directly loads the kernel library and uses torch.ops.npu.permute.
"""
import torch
import torch.nn as nn
from pathlib import Path

# Load kernel library from kernel/build directory
_THIS_DIR = Path(__file__).parent
_KERNEL_BUILD = _THIS_DIR / "kernel" / "build"
_loaded = False
for so_file in _KERNEL_BUILD.glob("permute_ext*.so"):
    try:
        torch.ops.load_library(str(so_file))
        _loaded = True
        break
    except Exception:
        pass

if not _loaded:
    # Try any permute_ext .so in parent dirs
    for parent in [_THIS_DIR.parent, _THIS_DIR.parent.parent]:
        for so_file in parent.glob("**/permute_ext*.so"):
            try:
                torch.ops.load_library(str(so_file))
                _loaded = True
                break
            except Exception:
                pass


class ModelNew(nn.Module):
    """Permute operator using AscendC kernel."""

    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor, dims: tuple) -> torch.Tensor:
        dims_tensor = torch.tensor(list(dims), dtype=torch.int64, device=x.device)
        return torch.ops.npu.permute(x, dims_tensor)
