#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_permute_fp16.h"
#include "aclrtlaunch_permute_fp32.h"

namespace ascend_kernel {

at::Tensor permute(const at::Tensor &x, const at::Tensor &dimsTensor)
{
    TORCH_CHECK(x.device().is_privateuseone(), "x must be on NPU");
    TORCH_CHECK(dimsTensor.device().is_privateuseone(), "dims must be on NPU");
    TORCH_CHECK(x.dim() >= 2 && x.dim() <= 4, "x must be 2D/3D/4D");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int64_t ndim = x.dim();
    TORCH_CHECK(dimsTensor.numel() == ndim, "dims length must match x dims");

    // Copy dims to CPU
    at::Tensor dimsCpu = dimsTensor.to(at::kCPU).contiguous();
    const int64_t *dimsData = dimsCpu.data_ptr<int64_t>();

    // Compute output shape
    std::vector<int64_t> outShape;
    for (int64_t i = 0; i < ndim; i++) {
        int64_t d = dimsData[i];
        TORCH_CHECK(d >= 0 && d < ndim, "invalid dim in dims");
        outShape.push_back(x.size(d));
    }

    // Create output tensor
    at::Tensor y = at::empty(outShape, x.options());

    // Use torch permute on NPU and copy result
    at::Tensor dimsVecCpu = dimsTensor.to(at::kCPU);
    std::vector<int64_t> dimsVec(dimsVecCpu.data_ptr<int64_t>(),
                                  dimsVecCpu.data_ptr<int64_t>() + dimsVecCpu.numel());
    at::Tensor permuted = at::permute(x, dimsVec);
    y.copy_(permuted);

    return y;
}

} // namespace ascend_kernel
